  if (!git(['status', '--porcelain']).trim()) return null
  git(['-c', 'user.name=flock', '-c', 'user.email=flock@ultrapowers.invalid', 'commit', '-qm', message])
  return git(['rev-parse', 'HEAD']).trim()
}
